//! Every contract test vector decodes with this crate's types.
//!
//! The vectors (`tests/vectors/*.json`) are generated by Core from its real
//! IPC handlers (see Core's `contract_tests.rs`); Controllers can decode the
//! same files in their own tests to stay in sync with Core's actual shapes.

use msst_ipc_protocol::{IpcMessage, IpcResponse};
use std::path::PathBuf;

#[test]
fn all_vectors_decode() {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors");
    let mut count = 0;
    for entry in std::fs::read_dir(&dir).expect("vectors dir") {
        let path = entry.unwrap().path();
        let text = std::fs::read_to_string(&path).unwrap();
        let v: serde_json::Value = serde_json::from_str(&text).unwrap();
        let name = path.file_name().unwrap().to_string_lossy().to_string();
        if let Some(events) = v.as_array() {
            for e in events {
                let m: IpcMessage = serde_json::from_value(e.clone()).unwrap_or_else(|err| panic!("{}: {}", name, err));
                assert!(matches!(m, IpcMessage::Event { .. }), "{}", name);
            }
        } else {
            let req: IpcMessage = serde_json::from_value(v["request"].clone()).unwrap_or_else(|e| panic!("{} request: {}", name, e));
            assert!(matches!(req, IpcMessage::Request { .. }), "{}", name);
            let resp: IpcMessage = serde_json::from_value(v["response"].clone()).unwrap_or_else(|e| panic!("{} response: {}", name, e));
            match resp {
                IpcMessage::Response { body: IpcResponse::Error(e), .. } => {
                    assert!(msst_ipc_protocol::errors::ALL.contains(&e.code.as_str()), "{}: undocumented code {}", name, e.code)
                }
                IpcMessage::Response { .. } => {}
                _ => panic!("{}: not a response", name),
            }
        }
        count += 1;
    }
    assert!(count >= 20, "expected the full vector set, found {}", count);
}

/// The typed views (`views`) decode Core's actual responses.
#[test]
fn typed_views_decode_vectors() {
    use msst_ipc_protocol::views;
    let data = |name: &str| -> serde_json::Value {
        let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors").join(name);
        let v: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
        assert_eq!(v["response"]["body"]["status"], "ok", "{}", name);
        v["response"]["body"]["data"].clone()
    };
    let h: views::Health = serde_json::from_value(data("health.json")).expect("health");
    assert_eq!(h.status, "ok");
    let n: views::Nodes = serde_json::from_value(data("get_nodes.json")).expect("get_nodes");
    assert!(!n.nodes.is_empty());
    let d: views::NodeDetail = serde_json::from_value(data("get_node.json")).expect("get_node");
    assert_eq!(d.node.device_id, "device-0000000b");
}
